'use strict';
const DICE_ORIENTATIONS={1:[0,0],2:[0,-90],3:[-90,0],4:[90,0],5:[0,90],6:[0,180]};
class DiceVisual{
 constructor(row){this.row=row;this.motion=matchMedia('(prefers-reduced-motion: reduce)');this.angles=[[0,0],[0,0],[0,0]];this.raf=0;const pips={1:[4],2:[0,8],3:[0,4,8],4:[0,2,6,8],5:[0,2,4,6,8],6:[0,2,3,5,6,8]};row.innerHTML=Array.from({length:3},()=>`<div class="die-slot"><div class="die-camera"><div class="die" role="img">${[1,2,3,4,5,6].map(v=>`<div class="die-core face-${v}" aria-hidden="true"></div>`).join('')}${[1,2,3,4,5,6].map(v=>`<div class="die-face face-${v}" aria-hidden="true">${pips[v].map(p=>`<span class="pip" style="grid-area:${Math.floor(p/3)+1}/${p%3+1}"></span>`).join('')}</div>`).join('')}</div></div><span class="die-shadow"></span></div>`).join('');this.cubes=[...row.querySelectorAll('.die')];this.slots=[...row.querySelectorAll('.die-camera')];this.shadows=[...row.querySelectorAll('.die-shadow')];this.snap([1,3,5]);}
 paint(){this.cubes.forEach((el,i)=>{const [x,y]=this.angles[i],p=this.poses?.[i]||{spin:0,tilt:0},tx=-35.26438968*p.tilt,tz=45*p.tilt;const support=diceSupport(tx,tz,x,y);el.style.transform=`translateY(calc(var(--depth) * ${1-support})) rotateY(${p.spin}deg) rotateX(${tx}deg) rotateZ(${tz}deg) rotateX(${x}deg) rotateY(${y}deg)`;if(this.shadows?.[i]){this.shadows[i].style.transform=`scale(${1-.28*p.tilt},${1-.14*p.tilt})`;this.shadows[i].style.opacity=String(.7+.3*p.tilt);}});}
 snap(values){cancelAnimationFrame(this.raf);this.angles=values.map(v=>[...DICE_ORIENTATIONS[v]]);this.poses=values.map(()=>({spin:0,tilt:0}));this.cubes.forEach((el,i)=>el.setAttribute('aria-label',values[i]+' 点'));this.paint();}
 roll(){cancelAnimationFrame(this.raf);this.cubes.forEach(el=>el.setAttribute('aria-label','单角旋转中'));this.row.setAttribute('aria-label','三颗骰子正在单角旋转');if(this.motion.matches)return;const start=performance.now();this.poses=[0,1,2].map(()=>({spin:0,tilt:0}));const tick=now=>{const t=(now-start)/1000;this.poses=this.poses.map((_,i)=>{const local=Math.max(0,t-i*.055),rise=Math.min(1,local/.28),ease=rise*rise*(3-2*rise);return {tilt:ease,spin:(700+i*65)*Math.max(0,local-.1)};});this.paint();this.raf=requestAnimationFrame(tick);};this.raf=requestAnimationFrame(tick);}
 settle(values,done){cancelAnimationFrame(this.raf);if(this.motion.matches){this.snap(values);done();return;}const start=performance.now(),base=this.angles.map(a=>[...a]),poses=this.poses.map(p=>({...p}));const tick=now=>{let complete=true;this.angles=base.map((a,i)=>{const t=Math.min(1,Math.max(0,(now-start-i*100)/700));if(t<1)complete=false;const slow=1-Math.pow(1-t,3),tip=Math.min(1,Math.max(0,(t-.42)/.58)),ease=tip*tip*(3-2*tip),endSpin=(Math.floor(poses[i].spin/360)+1)*360;this.poses[i]={spin:poses[i].spin+(endSpin-poses[i].spin)*slow,tilt:poses[i].tilt*(1-ease)*(1+.065*Math.sin(t*25)*Math.sin(Math.PI*t))};return a.map((v,j)=>v+(DICE_ORIENTATIONS[values[i]][j]-v)*ease);});this.paint();if(complete){this.snap(values);done();}else this.raf=requestAnimationFrame(tick);};this.raf=requestAnimationFrame(tick);}
}
// Support height of the rotated cube keeps its lowest corner on the same plane.
function diceSupport(tx,tz,x,y){const rad=a=>a*Math.PI/180,rx=(v,a)=>[v[0],v[1]*Math.cos(rad(a))-v[2]*Math.sin(rad(a)),v[1]*Math.sin(rad(a))+v[2]*Math.cos(rad(a))],ry=(v,a)=>[v[0]*Math.cos(rad(a))+v[2]*Math.sin(rad(a)),v[1],-v[0]*Math.sin(rad(a))+v[2]*Math.cos(rad(a))],rz=(v,a)=>[v[0]*Math.cos(rad(a))-v[1]*Math.sin(rad(a)),v[0]*Math.sin(rad(a))+v[1]*Math.cos(rad(a)),v[2]];return [[1,0,0],[0,1,0],[0,0,1]].reduce((sum,v)=>sum+Math.abs(rx(rz(rx(ry(v,y),x),tz),tx)[1]),0);}
if(typeof module!=='undefined')module.exports={DICE_ORIENTATIONS,diceSupport};
